import{_ as r}from"./chunks/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.PbWTgDXx.js";import{_ as s,o as a,c as l,j as e,a as n,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/import-export-statistik/tutorials-statistik-schaubild.png",d="/bilder/import-export-statistik/tutorials-statistik-supportangebote.png",o="/bilder/import-export-statistik/tutorials-statistik-asdpc-hilfe.png",h="/bilder/import-export-statistik/tutorials-statistik-asdpc-hilfe-index.png",c="/bilder/import-export-statistik/tutorials-statistik-organisationsform-usw.png",g="/bilder/import-export-statistik/tutorials-statistik-abschluss.png",p="/bilder/import-export-statistik/tutorials-statistik-id-i-status.png",m="/bilder/import-export-statistik/tutorials-statistik-abitur.png",_=JSON.parse('{"title":"Die amtliche Schulstatistik vorbereiten","description":"","frontmatter":{"title":"Die amtliche Schulstatistik vorbereiten","source_pageid":1199,"source_revision":6530},"headers":[],"relativePath":"schild3/import-export-statistik/vorbereitende-massnahmen-zur-statistik-in-schild-nrw-tutorial.md","filePath":"schild3/import-export-statistik/vorbereitende-massnahmen-zur-statistik-in-schild-nrw-tutorial.md"}'),b={name:"schild3/import-export-statistik/vorbereitende-massnahmen-zur-statistik-in-schild-nrw-tutorial.md"};function k(f,i,S,w,z,v){return a(),l("div",null,[...i[0]||(i[0]=[e("h1",{id:"die-amtliche-schulstatistik-vorbereiten",tabindex:"-1"},[n("Die amtliche Schulstatistik vorbereiten "),e("a",{class:"header-anchor",href:"#die-amtliche-schulstatistik-vorbereiten","aria-label":'Permalink to "Die amtliche Schulstatistik vorbereiten"'},"​")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Geltungsbereich: ASDPC-Verfahren")]),e("p",null,[n("Dieser Artikel beschreibt die Vorbereitung beziehungsweise Nutzung des bisherigen ASDPC-Verfahrens. Für die amtliche Erhebung "),e("strong",null,"ab dem Schuljahr 2027/2028"),n(" ist die Umstellung auf das Statistikmodul des SVWS-Servers angekündigt. Beachten Sie den "),e("a",{href:"https://www.svws.nrw.de/statistik/asdpc-svws-server",target:"_blank",rel:"noreferrer"},"offiziellen Zeitplan"),n(" und die Vorgaben der jeweiligen Erhebung.")])],-1),t('<p>Bereiten Sie die benötigten Schuldaten vor, führen Sie die Gesamtprüfung durch und arbeiten Sie gefundene Fehler ab. Anschließend können Sie die Dateien für ASDPC exportieren.</p><h2 id="ablauf-der-statistik" tabindex="-1">Ablauf der Statistik <a class="header-anchor" href="#ablauf-der-statistik" aria-label="Permalink to &quot;Ablauf der Statistik&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/tutorials-statistik-schaubild.png"><img src="'+u+'" alt="Der Ablauf der Statistik amtlichen Schulstatistik. Dieser Artikel bezieht sich auf die Vorbereitung mit SchILD-NRW." loading="lazy"></a></p><p><em>Der Ablauf der Statistik amtlichen Schulstatistik. Dieser Artikel bezieht sich auf die Vorbereitung mit SchILD-NRW.</em></p><p>Die amtliche Schulstatistik wird mit dem von IT.NRW bereitgestellten Programm ASDPC erzeugt. Da sich viele der Daten schon im Schulverwaltungsprogramm SchILD-NRW befinden, bietet es sich an, diese Daten soweit wie möglich vorzubereiten und dann in ASDPC zu importieren.</p><p>Grundsätzlich lassen sich auch alle benötigten Daten in ASDPC von Hand eintragen. Zur Arbeitsentlastung bietet SchILD-NRW an, Schülerdaten als SIM.txt, Lehrerdaten als LID.txt, Daten zur Unterrichtsverteilung als UVD.txt und zu den Abiturdaten als ABI.txt zu exportieren und im eigentlichen Statistikprogramm einzulesen.</p><h3 id="supportangebote" tabindex="-1">Supportangebote <a class="header-anchor" href="#supportangebote" aria-label="Permalink to &quot;Supportangebote&quot;">​</a></h3><h4 id="downloadseite-zu-asdpc" tabindex="-1">Downloadseite zu ASDPC <a class="header-anchor" href="#downloadseite-zu-asdpc" aria-label="Permalink to &quot;Downloadseite zu ASDPC&quot;">​</a></h4><p><a href="/bilder/import-export-statistik/tutorials-statistik-supportangebote.png"><img src="'+d+'" alt="Nutzen Sie die gestuften Supportangebote." loading="lazy"></a></p><p><em>Nutzen Sie die gestuften Supportangebote.</em></p><p>Die erste Anlaufstelle sollte der Abschnitt zur Statistik auf der <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">Webseite des Ministeriums für Schulverwaltungssoftware</a> sein.</p><p>Hier pflegt IT.NRW jährlich die für die Statistik relevanten Informationen ein und stellt die Downloads wie die nach Schulform differenzierten Eintragungshilfen und die Schlüsseltabellen zur Verfügung.</p><p>Auf der Downloadseite von ASDPC finden sich Informationen zu typischen Problemen bei der Installation, Konfiguration und Nutzung von ASDPC. Ebenso finden sich Informationen zu Änderungen der aktuellen Haupterhebung zum Vorjahr, die Schulmail zur Statistik und das Anschreiben, in welchem wiederum Informationen wie die Termine usw. zu finden sind.</p><p>Ebenso finden sich Informationen zum Support wie zum Schlüsselmanagement, zum Registrieren von für ASDPC notwendigen Windows-Komponenten und zu diversen Problemstellungen.</p><p>Diese Seite ist eine zentrale Anlaufstelle für die Verwendung von ASDPC.</p><p>Kontaktieren Sie bei technischen Problemen mit ASDPC bitte den Support von IT.NRW.</p><p>Weiterhin finden sich hier auch die Updates und die Updateanleitung für ASDPC.</p><h4 id="weitere-supportangebote-zur-inhaltlichen-arbeit" tabindex="-1">Weitere Supportangebote zur inhaltlichen Arbeit <a class="header-anchor" href="#weitere-supportangebote-zur-inhaltlichen-arbeit" aria-label="Permalink to &quot;Weitere Supportangebote zur inhaltlichen Arbeit&quot;">​</a></h4><p>Bei inhaltlichen Problemen wenden sie sich an die Supportangebote der Fachberatung.</p><p>Zur Selbsthilfe zur Verwendung von SchILD-NRW dieses <strong>Wiki</strong> zur Verfügung.</p><p>Zu SchILD-NRW und der jährlichen Statistik finden sich weiterhin passende Bereiche im <strong>Forum</strong>, die für ASDPC relevanten Unterforen werden auch von Mitarbeitern von IT.NRW überwacht. Im Forum kann die Suchfunktion zu bestehenden Themen verwendet werden und es können neue Fragen gepostet werden, die in der Regel auch relativ schnell beantwortet werden.</p><p>Kontaktieren Sie bei weiteren Problemen den Ihrer Schule zugeordneten Fachberater (m/w/d). Sie finden die Kontaktdaten über die <strong>Fachberatersuche</strong> im <strong>Service</strong>bereich der Webseite für Schulverwaltungssoftware des Ministeriums.</p><p>Bauen Sie längerfristig Kompetenz durch den Besuch eventuell angebotener <strong>Statistikschulungen Ihrer Bezirksregierung</strong> auf.</p><h3 id="hilfen-in-asdpc" tabindex="-1">Hilfen in ASDPC <a class="header-anchor" href="#hilfen-in-asdpc" aria-label="Permalink to &quot;Hilfen in ASDPC&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/tutorials-statistik-asdpc-hilfe.png"><img src="'+o+'" alt="Das Hilfemenü von ASDPC, über das zum Beispiel der Direktlink zu passenden Schlüsseltabellen aufgerufen werden kann." loading="lazy"></a></p><p><em>Das Hilfemenü von ASDPC, über das zum Beispiel der Direktlink zu passenden Schlüsseltabellen aufgerufen werden kann.</em></p><p><a href="/bilder/import-export-statistik/tutorials-statistik-asdpc-hilfe-index.png"><img src="'+h+'" alt="Der Index von ASDPC, in dem sich Informationen zur Statistik und zu den Belegen nachschlagen lässt." loading="lazy"></a></p><p><em>Der Index von ASDPC, in dem sich Informationen zur Statistik und zu den Belegen nachschlagen lässt.</em></p><p>ASDPC selbst bietet viele Hilfen an.</p><p>Zum Beispiel ist über <em>Hilfe</em> ➜ <strong>Inhalt</strong> direkt aus der Haupterhebung heraus der ausführliche <strong>Index</strong> abrufbar, über den sich vieles zur Statistik, nützlichen Hinweisen auch - zur Statistik des aktuellen Schuljahrs - und zu den konkreten Belegen nachschlagen lässt.</p><p>Der Index beinhaltet auch eine Suchfunktion.</p><p>Der Eintrag <strong>Eintragungshilfen/Schlüsseltabellen</strong> öffnet eine Auswahl, mit der die <em>Schlüsseltabellen</em> oder <em>Eintragungshilfen</em> Ihrer Schulform direkt aus ASDPC im Browser geöffnet werden.</p><p>Über den Eintrag <strong>Schulverzeichnis</strong> wird das Verzeichnis mit allen Schulen in NRW der aktuell verwendeten SCHULVER.MDB geöffnet</p><p>Abschließend zeigt <strong>Info</strong> Daten zur Dateiversion von ASDPC und der verwendeten Daten. Diese sehen Sie auch direkt im Startbildschirm. Hier lässt sich kontrollieren, ob tatsächlich die korrekte, aktuelle Version von ASDPC verwendet wird.</p><h2 id="vorbereitung-der-statistik-in-schild-nrw" tabindex="-1">Vorbereitung der Statistik in SchILD-NRW <a class="header-anchor" href="#vorbereitung-der-statistik-in-schild-nrw" aria-label="Permalink to &quot;Vorbereitung der Statistik in SchILD-NRW&quot;">​</a></h2>',35),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,[e("strong",null,"Pflege der zur Statistik verwendeten Software:")]),e("ol",null,[e("li",null,"Führen Sie bitte für das von IT.NRW angebotene ASDPC und für SchILD-NRW die jeweils aktuellen Updates aus, da in ihnen auch die Grundlagen für die aktuelle Statistik ausgeliefert werden."),e("li",null,"Schauen Sie weiterhin auch während der Statistik, ob für beide Programme noch Hotfixes für kurzfristig gefundene Fehler zur Verfügung gestellt wurden."),e("li",null,"Achten Sie darauf, die Statistik mit der für dieses Jahr aktuellen Version von ASDPC zu erstellen."),e("li",null,"Ist SchILD-NRW in einer Netzwerkumgebung installiert, achten Sie darauf, wo die .dlls und .mdbs mit den aktuellen Daten abgelegt werden und registriert sind - auf dem lokalen Rechner oder in der Netzwerkinstallation?")])],-1),e("h3",{id:"statistikrelevante-felder-in-schild-nrw",tabindex:"-1"},[n("Statistikrelevante Felder in SchILD-NRW "),e("a",{class:"header-anchor",href:"#statistikrelevante-felder-in-schild-nrw","aria-label":'Permalink to "Statistikrelevante Felder in SchILD-NRW"'},"​")],-1),e("p",null,[e("a",{href:"/bilder/benutzer-einstellungen/verwaltung-einstellungen-individual-einstellungen-farbe-statistik.png"},[e("img",{src:r,alt:"Stellen Sie die Farbe ein, in der statistikrelevante Felder hervorgehoben werden. Hier im Beispiel wurde blau gewählt.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Stellen Sie die Farbe ein, in der statistikrelevante Felder hervorgehoben werden. Hier im Beispiel wurde blau gewählt.")],-1),e("p",null,[n("SchILD-NRW kennzeichnet Felder, die für die Statistik relevant sind. Per Standard werden "),e("strong",null,"statistikrelevante Felder*"),n(' durch Fettdruck und ein Sternchen "'),e("strong",null,"*"),n('" gekennzeichnet.')],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Über "),e("em",null,"Verwaltung ➜ Einstellungen ➜ Individuelle Einstellungen ➜ Benutzeroberfläche"),n(" ➜ "),e("strong",null,"Farbe für statistikrelevante Felder"),n(" lassen sich diese Überschriften zusätzlich noch einfärben.")])],-1),e("p",null,"Nicht alle statistikrelevanten Felder müssen auch ausgefüllt werden, auch ein Nicht-Eintrag kann korrekt sein.",-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Wenn sich ein Schüler zum Beispiel nicht von Religion abgemeldet hat, bleiben die Datumsfelder zur "),e("em",null,"An-/Abmeldung vom Religionsunterricht natürlich leer.")])],-1),e("p",null,"Alle statistikrelevanten Felder sind so korrekt wie möglich auszufüllen, da diese Daten dann nach ASDPC exportiert werden können und dort vorhanden sind und genutzt werden können, um miteinander in Bezug gesetzt zu werden.",-1),e("p",null,"Felder, die korrekt ausgefüllt sind, sparen bei der Statistik Arbeit - und stehen auch im nächsten Jahr wieder zum korrekten Export zur Verfügung.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Hierbei empfiehlt es sich, dass sich die mit der Dateneingabe und -pflege in SchILD befassten Personen mit der mit der Statistik beauftragten Person koordinieren.")],-1),t('<h3 id="haupt-und-weitere-forderschwerpunkte" tabindex="-1">Haupt- und weitere Förderschwerpunkte <a class="header-anchor" href="#haupt-und-weitere-forderschwerpunkte" aria-label="Permalink to &quot;Haupt- und weitere Förderschwerpunkte&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/tutorials-statistik-organisationsform-usw.png"><img src="'+c+'" alt="Eintragungen zu Förderschwerpunkten, Organisationsform, AO-SF und Zieldifferentem Lernen und ähnlich werden über das Akt. Halbjahr zum jeweiligen Lernabschnitt vorgenommen." loading="lazy"></a></p><p><em>Eintragungen zu Förderschwerpunkten, Organisationsform, AO-SF und Zieldifferentem Lernen und ähnlich werden über das Akt. Halbjahr zum jeweiligen Lernabschnitt vorgenommen.</em></p><p>Setzen Sie im <em>aktuellen Halbjahr</em> alle <strong>Förderschwerpunkte</strong>. Diese sind im Screenshot rechts ebenfalls hervorgehoben.</p><p>Beachten Sie hierbei die Schlüsseltabellen von IT.NRW, damit im <strong>Förderschwerpunkt</strong> nur zugelassene Hauptförderschwerpunkte und nur zugelassene Kombinationen aus <strong>Förderschwerpunkt</strong> und <strong>Weiterer Förderschwerpunkt</strong> gesetzt werden.</p><p>Die hier gesetzten und zum aktuellen Lernabschnitt gehörenden Daten werden unter <em>Individualdaten II</em> im Nur-Lesemodus angezeigt.</p><p>Nehmen Sie hierzu das Tutorial zu den <a href="/schild3/unterricht-kataloge/foerderschwerpunkte-allgemeine-kataloge.html">Förderschwerpunkten</a> zu Kenntnis.</p><h3 id="besonderheiten-nach-schulform" tabindex="-1">Besonderheiten nach Schulform <a class="header-anchor" href="#besonderheiten-nach-schulform" aria-label="Permalink to &quot;Besonderheiten nach Schulform&quot;">​</a></h3><h4 id="grundschulen-ogs-und-andere-betreuungsformen" tabindex="-1">Grundschulen: OGS und andere Betreuungsformen <a class="header-anchor" href="#grundschulen-ogs-und-andere-betreuungsformen" aria-label="Permalink to &quot;Grundschulen: OGS und andere Betreuungsformen&quot;">​</a></h4><p>Für die Grundschulen sind die <strong>Organisationsform</strong> <em>&quot;offener Ganztag&quot;</em> in den aktuellen Lernabschnitt unter <em>&quot;Akt. Halbjahr&quot;</em> einzutragen.</p><p>Besondere Merkmale, wie etwa die <em>Schule von acht bis eins</em> oder <em>Dreizehn plus</em> werden als <strong>Merkmale</strong> unter <em>Verwaltung ➜ Schule ➜ Weitere Angaben</em> einmalig angelegt und dann in den <em>Individualdaten II</em> aufgenommen.</p><p>Die zu den aktuellen Laufbahndaten gehörenden <em>Individualdaten I</em> und die zur Förderung zum aktuellen Lernabschnitt gehörenden unter den <em>Individualdaten II</em> im Nur-Lesenmodus aufgeführt.</p>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Beachten Sie hierzu den Screenshot zu den "),e("em",null,"Förderschwerpunkten"),n(" oben.")])],-1),t('<p>Konsultieren Sie hierzu das Tutorial zu <a href="/schild3/schueler/eintragung-der-schueler-im-offenen-ganztag-tutorial.html">Ganztag und Betreuungsangebote erfassen</a>.</p><h4 id="grund-und-forderschulen-klassenversetzungstabelle-bei-jahrgangsgemischten-lerngruppen" tabindex="-1">Grund- und Förderschulen: Klassenversetzungstabelle bei jahrgangsgemischten Lerngruppen <a class="header-anchor" href="#grund-und-forderschulen-klassenversetzungstabelle-bei-jahrgangsgemischten-lerngruppen" aria-label="Permalink to &quot;Grund- und Förderschulen: Klassenversetzungstabelle bei jahrgangsgemischten Lerngruppen&quot;">​</a></h4><p>Wird in der Schuleingangsphase oder auch in höheren Jahrgängen <em>jahrgangsgemischt</em> unterrichtet, sind bei den entsprechenden Klassen der jeweilige <strong>Jahrgang</strong> auf <em>JU</em> zu setzen.</p><p>Entsprechend werden in der Regel auch Klassenbezeichnungen gesetzt, der Jahrgangsmischung Rechnung tragen, d.h. die Klassen werden keine Jahrgangsbezeichnung (&quot;1a&quot;, &quot;6.2&quot; oder vergleichbar) enthalten.</p><p>Beachten Sie hierzu das Tutorial zum <a href="/zeugnisse/grundschule/versetzungstabelle-bei-jahrgangsgemischten-klassen-tutorial.html">Unterricht in jahrgangsgemischten Lerngruppen</a>.</p><h3 id="abschlussjahrgange-abschluss-abganger" tabindex="-1">Abschlussjahrgänge: Abschluss/Abgänger <a class="header-anchor" href="#abschlussjahrgange-abschluss-abganger" aria-label="Permalink to &quot;Abschlussjahrgänge: Abschluss/Abgänger&quot;">​</a></h3><p><a href="/bilder/import-export-statistik/tutorials-statistik-abschluss.png"><img src="'+g+'" alt="Die Daten zum Abschluss/Nicht-Abschluss bei Schüler Akt. ➜ Halbjahr. Im Beispiel fehlt noch der konkrete Abschluss." loading="lazy"></a></p><p><em>Die Daten zum Abschluss/Nicht-Abschluss bei Schüler Akt. ➜ Halbjahr. Im Beispiel fehlt noch der konkrete Abschluss.</em></p><p>Erfassen Sie Abschlüsse und Abgänge vollständig. ASDPC prüft anhand der Vorjahresstatistik, wie viele Schülerinnen und Schüler die Schule voraussichtlich verlassen haben. Die Angaben müssen deshalb auch im Vergleich zum Vorjahr schlüssig sein.</p><p>Tragen Sie bei den Schülern, die einen Abschluss erreicht haben diesen im <em>Akt. Halbjahr</em> ein. Tragen Sie unter <strong>Abschluss-Art</strong> den Eintrag <em>mit Abschluss</em> ein, dann wählen Sie den passenden <strong>Abschluss</strong> aus der Dropdown-Liste.</p><p>Schüler, die keinen <em>Abschluss</em> erreichen, erhalten als <strong>Abschluss-Art</strong> den &quot;Abschluss&quot; <em>ohne Abschuss</em> oder <em>ohne Abschluss mit Nachprüf.</em> ein.</p><p><a href="/bilder/import-export-statistik/tutorials-statistik-id-i-status.png"><img src="'+p+'" alt="Setzen des Status über die Individualdaten I. Bei abgehenden Schülern sind die Feldwerte Abschluss oder Abgänger relevant." loading="lazy"></a></p><p><em>Setzen des <strong>Status</strong> über die Individualdaten I. Bei abgehenden Schülern sind die Feldwerte Abschluss oder Abgänger relevant.</em></p><p>Nur Schülerinnen und Schüler, die die Schule tatsächlich verlassen, werden ausgeschult. Ein Zeugnisdruck allein ist kein Anlass, alle Datensätze auf den <strong>Status Abschluss</strong> zu setzen; unterscheiden Sie Abschlussangaben im Lernabschnitt, Status und tatsächliches Abgangsdatum.</p>',14),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Abschlussberechnungen und Abschlüsse können Sie gruppenweise verarbeiten. Einzelne Abgänge während des Schuljahres bearbeiten Sie in der Regel am jeweiligen Schülerdatensatz.")],-1),t('<p>Setzen Sie abgemeldete Schülerinnen und Schüler unter <strong>Individualdaten I</strong> auf den <strong>Status Abgang</strong>. Für mehrere Personen verwenden Sie <strong>Individualdaten ändern</strong> oder <strong>Zeugnisse drucken und Schüler ausschulen</strong>.</p><p>Wird der Gruppenprozess <em>Zeugnisse drucken und Schüler ausschulen</em> ausgeführt, werden die entsprechenden Werte wie die Statusänderung oder das Abgangsdatum automatisch gesetzt.</p><p><a href="/bilder/import-export-statistik/tutorials-statistik-abitur.png"><img src="'+m+'" alt="Entlassung mit Abitur in der Q2. Statistikrelevant sind hier das Entlassdatum und die Art des Abschlusses. Um den Abschluss zu setzen, wird in SchILD-NRW zwingend der Entlassjahrgang benötigt, so dass alle relevanten Daten auch aufgenommen sind." loading="lazy"></a></p><p><em>Entlassung mit Abitur in der Q2. Statistikrelevant sind hier das Entlassdatum und die Art des Abschlusses. Um den Abschluss zu setzen, wird in SchILD-NRW zwingend der Entlassjahrgang benötigt, so dass alle relevanten Daten auch aufgenommen sind.</em></p><p>Tragen Sie bei Gelegenheit auch unter <em>Schüler ➜ Schulbesuch</em> die zutreffenden Daten bei <strong>Entlassung von eigener Schule</strong> und <strong>Wechsel zu aufnehmender Schule</strong> ein.</p><p>Beachten Sie zum <em>Abitur</em> den Gruppenprozess <em>Abitur-Jahr setzen</em>.</p>',6),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Auch hier sind passende Gruppenprozesse hilfreich."),e("p",null,"In ASDPC müssen alle Schüler des Vorjahres in Jahrgängen mit möglichen Abschlüssen korrekt verbucht sein. Es empfiehlt sich, die Daten schon in SchILD-NRW vollständig aufzubereiten.")],-1),e("p",null,[n("Beachten Sie, dass die Felder "),e("strong",null,"Entlassung am"),n(" und "),e("strong",null,"Art des Abschlusses (bei erfüllter Schulpflicht erforderlich)"),n(" statistikrelevant sind.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Für "),e("strong",null,"alle Schulformen"),n(" gilt: Schulen Sie die zum Schuljahresende abgemeldeten Personen mit dem Status "),e("strong",null,"Abgang"),n(" vor der Versetzung aus. Andernfalls werden auch für diese Personen neue Lernabschnitte angelegt, obwohl sie Ihre Schule nicht mehr besuchen.")]),e("p",null,[n("In "),e("strong",null,"Grundschulen"),n(" haben Schüler nach der 4. Klasse den Eintrag "),e("em",null,"Abschluss"),n(" in der "),e("strong",null,"Abschluss-Art"),n(". Denken Sie bei Viertklässlern daran, in "),e("em",null,"Schüler ➜ Individualdaten II"),n(" die "),e("strong",null,"Übergangsempfehlung für Jg. 5"),n(" zu setzen.")])],-1),t('<p>Beachten Sie zu dieser Thematik den umfangreichen Artikel zu <a href="/einstieg/grundlagen/zeugnisvorbereitungen-und-zeugnisdruck-einfuehrung-in-schild-nrw.html">Zeugnisvorbereitungen und Zeugnisdruck in SchILD-NRW</a>.</p><p>Weiterhin sind die Gruppenprozesse zur Versetzungs- und Abschlussberechnung zu beachten. Da dieses Thema aufgrund von ZP 10/ZK beziehungsweise der Fachhochschulreife, ESA, MSA, Abitur usw. komplexer ist und es mehrere Wege gibt, die je nach Jahrgang, Schule und Schulform zum Ziel führen, wird auf eine einzelne Verlinkung aller möglicherweise relevanten Artikel an dieser Stelle verzichtet.</p><p>Nutzen Sie je nach Aufgabe die Übersichtsartikel in dieser Dokumentation beziehungsweise die Reihenfolge der Gruppenprozesse und deren Übersicht in dieser Dokumentation zur Orientierung.</p><h2 id="ubergabe-der-daten-an-asdpc" tabindex="-1">Übergabe der Daten an ASDPC <a class="header-anchor" href="#ubergabe-der-daten-an-asdpc" aria-label="Permalink to &quot;Übergabe der Daten an ASDPC&quot;">​</a></h2><h3 id="gesamtprufung-und-fehlerkorrektur" tabindex="-1">Gesamtprüfung und Fehlerkorrektur <a class="header-anchor" href="#gesamtprufung-und-fehlerkorrektur" aria-label="Permalink to &quot;Gesamtprüfung und Fehlerkorrektur&quot;">​</a></h3><p>Führen Sie über <em>Verwaltung ➜ Statistik für IT.NRW</em> die <strong>Gesamtprüfung der Daten</strong> aus.</p><p>Lösen Sie die Statistikfehler auf und wiederholen Sie die Statistikprüfung, und prüfen Sie nach jedem Korrekturlauf das neue Protokoll. Klären Sie verbleibende Meldungen anhand der Eintragungshilfen; ändern Sie Daten nicht nur, um eine Meldung zu unterdrücken.</p><p>Weitere Anleitungen finden Sie unter <a href="/schild3/statistik.html">Die Schulstatistik vorbereiten und prüfen</a>.</p><p>Nehmen Sie besonders den Artikel <a href="/zeugnisse/vorbereitung/gesamtpruefung-der-daten-verwaltung-statistik-fuer-it-nrw.html">Die Gesamtprüfung für die Statistik durchführen</a> zur Kenntnis, hier wird auch die Bearbeitung der gefundenen Statistikfehler innerhalb von SchILD-NRW über die <em>Auswahl</em> der <em>Schüler mit Statikstfehlern</em> erläutert.</p><h3 id="export-der-txt-dateien" tabindex="-1">Export der txt-Dateien <a class="header-anchor" href="#export-der-txt-dateien" aria-label="Permalink to &quot;Export der txt-Dateien&quot;">​</a></h3><p>Schlussendlich werden die zu exportierenden Daten über <em>Verwaltung Statistik für IT.NRW</em> <strong>Daten exportieren</strong> ausgewählt.</p><p>Es können vier unterschiedliche Dateien erzeugt werden, die je nach Schulform und Arbeitsweise sehr hilfreich sind oder nicht benötigt werden könnten.</p><ul><li>Die Schülerdaten werden in die <em>SIM.txt</em> geschrieben.</li><li>Die Lehrerdaten werden in die <em>LID.txt</em> geschrieben.</li><li>Die Unterrichtsverteilung in die <em>UVD.txt</em> geschrieben.</li><li>Eventuelle Abiturdaten werden in die <em>ABI.txt</em> geschrieben.</li></ul>',13),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("ol",null,[e("li",null,"Obwohl SchILD-NRW beim Export ein umbenennen der Dateien zulässt, müssen die Standardnamen beibehalten werden, da ASDPC die Dateien ansonsten nicht einlesen kann."),e("li",null,"Stellen Sie beim Einlesen in ASDPC unbedingt sicher, dass die korrekten, gerade exportierten Dateien eingelesen werden und nicht etwa welche von einem vorherigen Export oder aus einem früheren Jahr.")])],-1),e("p",null,[n("Beachten Sie den Artikel "),e("a",{href:"/schild3/import-export-statistik/daten-exportieren-verwaltung-statistik-fuer-it-nrw.html"},"Statistikdaten für ASDPC exportieren"),n(" für den detaillierten Vorgang.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vorbereitende_Ma%C3%9Fnahmen_zur_Statistik_in_SchILD-NRW_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6530.")],-1)])])}const x=s(b,[["render",k]]);export{_ as __pageData,x as default};
